require('dotenv').config();
const express=require('express'),multer=require('multer'),crypto=require('crypto'),path=require('path'),fs=require('fs'),nodemailer=require('nodemailer');
const {q,one,run,setting,setSetting,DATA_DIR,db}=require('./db');
const {parseCv,CvError}=require('./cv');
const {matchJob,requirementsFromText,searchTerms,DEFAULT_WEIGHTS,STATUSES}=require('./matcher');
const {CONNECTORS,isNL,dedupeKey,importFromUrl}=require('./connectors');
const app=express();app.set('trust proxy',1);app.use(express.json({limit:'3mb'}));
const origins=(process.env.ALLOWED_ORIGINS||'').split(',').map(s=>s.trim()).filter(Boolean);
app.use((req,res,next)=>{const o=req.headers.origin;if(o&&origins.includes(o)){res.set({'Access-Control-Allow-Origin':o,'Access-Control-Allow-Headers':'authorization,content-type','Access-Control-Allow-Methods':'GET,POST,PATCH,PUT,DELETE',Vary:'Origin'});if(req.method==='OPTIONS')return res.sendStatus(204)}res.set({'X-Content-Type-Options':'nosniff','X-Frame-Options':'SAMEORIGIN','Referrer-Policy':'same-origin'});next()});
const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:15*1024*1024,files:1}});
const J=(v,d)=>{try{return v==null?d:JSON.parse(v)}catch{return d}};
const E=(status,msg)=>Object.assign(new Error(msg),{status,expose:true});
const h=fn=>(req,res,next)=>Promise.resolve(fn(req,res,next)).catch(next);
const PERM={'people.write':['super_admin','programme_manager','employment_advisor'],'training.write':['super_admin','programme_manager','training_coordinator'],'jobs.write':['super_admin','programme_manager','employment_advisor'],'config':['super_admin','programme_manager'],'admin':['super_admin']};
const STAFF_ROLES=['super_admin','programme_manager','employment_advisor','training_coordinator','read_only'];
const hashPw=(p,salt=crypto.randomBytes(16).toString('hex'))=>`${salt}:${crypto.scryptSync(p,salt,64).toString('hex')}`;
const checkPw=(p,st)=>{if(!st)return false;const [s,k]=st.split(':');return crypto.timingSafeEqual(Buffer.from(k,'hex'),crypto.scryptSync(p,s,64))};
const pwOk=p=>typeof p==='string'&&p.length>=10;
const newSession=uid=>{const token=crypto.randomBytes(32).toString('hex');run('INSERT INTO sessions VALUES(?,?,?)',crypto.createHash('sha256').update(token).digest('hex'),uid,Date.now()+864e5*7);return token};
function auth(req,res,next){const t=(req.headers.authorization||'').replace(/^Bearer /,'');if(t){const s=one('SELECT u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND s.expires>? AND u.active=1',crypto.createHash('sha256').update(t).digest('hex'),Date.now());if(s){req.user={...s,roles:J(s.roles,[])};delete req.user.hash}}next()}
app.use(auth);
const isStaff=u=>u&&u.roles.some(r=>STAFF_ROLES.includes(r));
const staff=(req,res,next)=>isStaff(req.user)?next():next(E(req.user?403:401,req.user?'Staff access only':'Please sign in'));
const can=p=>(req,res,next)=>!req.user?next(E(401,'Please sign in')):req.user.roles.some(r=>PERM[p].includes(r))?next():next(E(403,'Your role does not permit this action'));
const participantOf=req=>{if(!req.user)throw E(401,'Please sign in');const p=one('SELECT * FROM participants WHERE user_id=?',req.user.id);if(!p)throw E(403,'Participant account required');return p};
const audit=(req,action,entity,id,detail)=>run('INSERT INTO audit(user_id,user_name,action,entity,entity_id,detail,ip) VALUES(?,?,?,?,?,?,?)',req?.user?.id??null,req?.user?.name??'System',action,entity,String(id??''),detail?JSON.stringify(detail):null,req?.ip??'');
const hits=new Map();const limit=(n,ms)=>(req,res,next)=>{const k=req.path+req.ip,now=Date.now(),a=(hits.get(k)||[]).filter(t=>now-t<ms);if(a.length>=n)return next(E(429,'Too many attempts. Please wait and try again.'));a.push(now);hits.set(k,a);next()};
// ---- Mail
const smtp=process.env.SMTP_HOST?nodemailer.createTransport({host:process.env.SMTP_HOST,port:+(process.env.SMTP_PORT||587),secure:process.env.SMTP_SECURE==='1',auth:process.env.SMTP_USER?{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}:undefined}):null;
const fill=(t,v)=>t.replace(/\{\{(\w+)\}\}/g,(_,k)=>v[k]??'');
async function deliver(p,subject,body,meta={}){const to=meta.to||p?.email;let status='Portal only',error=null;
  if(smtp&&to){try{await smtp.sendMail({from:process.env.MAIL_FROM||process.env.SMTP_USER,to,subject,text:body});status='Sent'}catch(e){status='Failed';error=e.message}}else if(to)error='Email service is not configured, so this was delivered to the portal only.';
  return run('INSERT INTO messages(participant_id,to_email,subject,body,template,status,error,by_user) VALUES(?,?,?,?,?,?,?,?)',p?.id??null,to||'',subject,body,meta.template||null,status,error,meta.by??null)}
async function notify(key,p,vars={},req){const t=one('SELECT * FROM templates WHERE key=?',key);if(!t||!t.auto||!p)return;const v={name:p.name,code:p.code,...vars};await deliver(p,fill(t.subject,v),fill(t.body,v),{template:key,by:req?.user?.id})}
const appUrl=req=>process.env.PUBLIC_URL||`${req.protocol}://${req.get('host')}`;
// ---- Helpers
const setStage=(req,pid,stage,note)=>{run("UPDATE participants SET stage=?,updated=CURRENT_TIMESTAMP WHERE id=?",stage,pid);run('INSERT INTO stage_history(participant_id,stage,note,by_user) VALUES(?,?,?,?)',pid,stage,note||null,req?.user?.id??null);audit(req,'stage.change','participant',pid,{stage,note})};
const getP=id=>{const p=one('SELECT * FROM participants WHERE id=?',+id);if(!p)throw E(404,'Participant not found');return p};
const nextCode=()=>{const n=(one('SELECT MAX(id) m FROM participants').m||0)+1001;return `AM-${n}`};
const norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');
function findDuplicate(d,exclude){const e=norm(d.email),ph=String(d.phone||'').replace(/\D/g,'').slice(-10),n=norm(d.name);for(const p of q('SELECT id,name,email,phone FROM participants WHERE id IS NOT ?',exclude??null)){if(e&&norm(p.email)===e)return p.id;if(ph.length===10&&String(p.phone||'').replace(/\D/g,'').slice(-10)===ph)return p.id;if(n.length>5&&norm(p.name)===n)return p.id}return null}
function createParticipant(d,entry,userId,req){const dup=findDuplicate(d);const r=run("INSERT INTO participants(code,user_id,name,email,phone,city,entry,referral_source,staff_id,notes,duplicate_of,duplicate_state) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",nextCode(),userId??null,d.name,d.email||'',d.phone||'',d.city||'',entry,d.source||'',d.staff_id||null,d.notes||'',dup,dup?'Needs review':null);const id=Number(r.lastInsertRowid);run('INSERT INTO stage_history(participant_id,stage,note,by_user) VALUES(?,?,?,?)',id,'Application received',entry==='public'?'Public application':'Registered by staff',req?.user?.id??null);audit(req,'participant.create','participant',id,{entry,duplicate:dup});return id}
const required=(o,...k)=>{for(const x of k)if(!o||!String(o[x]??'').trim())throw E(400,`${x.replace(/_/g,' ')} is required`)};
function storeFile(file,pid,kind,by,programme=null){const sha=crypto.createHash('sha256').update(file.buffer).digest('hex'),stored=`${crypto.randomUUID()}.bin`;fs.writeFileSync(path.join(DATA_DIR,'files',stored),file.buffer);const r=run('INSERT INTO documents(participant_id,programme_id,kind,name,mime,stored,size,sha256,by_user) VALUES(?,?,?,?,?,?,?,?,?)',pid,programme,kind,file.originalname,file.mimetype,stored,file.size,sha,by??null);return Number(r.lastInsertRowid)}
async function addCv(pid,file,by){const parsed=await parseCv(file.buffer,file.originalname);const v=(one('SELECT MAX(version) v FROM cv_versions WHERE participant_id=?',pid).v||0)+1;const doc=storeFile(file,pid,'CV',by);const r=run('INSERT INTO cv_versions(participant_id,version,document_id,file_type,method,word_count,text,profile,warnings,by_user) VALUES(?,?,?,?,?,?,?,?,?,?)',pid,v,doc,parsed.fileType,parsed.method,parsed.wordCount,parsed.text,JSON.stringify(parsed.profile),JSON.stringify(parsed.warnings),by??null);return{id:Number(r.lastInsertRowid),version:v,...parsed}}
const latestCv=pid=>{const c=one('SELECT * FROM cv_versions WHERE participant_id=? ORDER BY version DESC LIMIT 1',pid);if(c)c.profile=J(c.profile,{});return c};
const weights=()=>setting('weights',DEFAULT_WEIGHTS);
const jobObj=j=>({...j,parsedRequirements:J(j.requirements,[]),descriptionTruncated:!!j.truncated});
const SEL_J='id,source_name,title,employer,location,type,salary,truncated,url,posted,closing,status,verified,first_seen,requirements,source_id';
function runMatch(job,p,cv){const prior=one('SELECT id,overrides FROM matches WHERE job_id=? AND participant_id=? AND cv_id=?',job.id,p.id,cv.id);const ov=J(prior?.overrides,{});const result=matchJob(jobObj(job),cv.profile,{weights:weights(),preferences:J(p.preferences,{}),overrides:ov});
  if(prior)run('UPDATE matches SET score=?,eligibility=?,confidence=?,result=?,at=CURRENT_TIMESTAMP WHERE id=?',result.score,result.eligibility,result.evidenceConfidence,JSON.stringify(result),prior.id);else run('INSERT INTO matches(job_id,participant_id,cv_id,score,eligibility,confidence,result) VALUES(?,?,?,?,?,?,?)',job.id,p.id,cv.id,result.score,result.eligibility,result.evidenceConfidence,JSON.stringify(result));
  return one('SELECT * FROM matches WHERE job_id=? AND participant_id=? AND cv_id=?',job.id,p.id,cv.id)}
const readyPool=()=>q("SELECT * FROM participants WHERE stage='Employment Ready' AND availability='Available for opportunities'");
function matchJobAgainstPool(job){let n=0;for(const p of readyPool()){const cv=latestCv(p.id);if(cv){runMatch(job,p,cv);n++}}return n}
function upsertJob(j,src){const dk=dedupeKey(j);const ex=one('SELECT id FROM jobs WHERE dedupe=?',dk);const reqs=JSON.stringify(requirementsFromText(j));
  if(ex){run("UPDATE jobs SET last_seen=CURRENT_TIMESTAMP,status=CASE WHEN status='Closed' AND ?=0 THEN status ELSE 'Open' END,description=CASE WHEN length(?)>length(COALESCE(description,'')) THEN ? ELSE description END,requirements=CASE WHEN length(?)>length(COALESCE(description,'')) THEN ? ELSE requirements END,url=COALESCE(NULLIF(url,''),?) WHERE id=?",src?1:0,j.description,j.description,j.description,reqs,j.url,ex.id);return{id:ex.id,isNew:false}}
  const r=run('INSERT INTO jobs(source_id,source_name,external_id,dedupe,title,employer,location,type,salary,description,truncated,requirements,url,posted,closing) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',src?.id??null,src?.name??j.sourceName??'Staff entry',j.externalId,dk,j.title,j.employer,j.location,j.type,j.salary,j.description,j.descriptionTruncated?1:0,reqs,j.url,j.posted,j.closing);return{id:Number(r.lastInsertRowid),isNew:true}}
function sourceRow(s){return{...s,config:J(s.config,{})}}
async function syncSource(sr,q0={}){const s=sourceRow(sr),c=CONNECTORS[s.kind];if(!c)throw E(400,'Unknown source type');for(const k of c.needs)if(!s.config[k])throw E(400,`${k} is not set for ${s.name}`);
  try{let res=await c.fetch(s,q0);const jobs=(Array.isArray(res)?res:res.jobs).filter(j=>j.title);const nl=jobs.filter(isNL);let added=0;const fresh=[];for(const j of nl){const u=upsertJob(j,s);if(u.isNew){added++;fresh.push(u.id)}}
    if(res.unchanged){run("UPDATE sources SET status='Connected',last_ok=CURRENT_TIMESTAMP,last_error=NULL WHERE id=?",s.id);run("UPDATE jobs SET last_seen=CURRENT_TIMESTAMP WHERE source_id=? AND status='Open'",s.id);return{source:s.name,retrieved:0,inNL:0,added:0,note:'Already up to date with the latest monthly file'}}
    run("UPDATE sources SET status='Connected',last_ok=CURRENT_TIMESTAMP,last_count=?,last_error=NULL,config=? WHERE id=?",jobs.length,JSON.stringify(s.config),s.id);
    for(const id of fresh){const job=one('SELECT * FROM jobs WHERE id=?',id);matchJobAgainstPool(job)}
    return{source:s.name,retrieved:jobs.length,inNL:nl.length,added}}
  catch(e){run("UPDATE sources SET status='Error',last_error=? WHERE id=?",e.message,s.id);throw e}}
function closeExpired(){const today=new Date().toISOString().slice(0,10);run("UPDATE jobs SET status='Closed' WHERE status='Open' AND closing<>'' AND closing IS NOT NULL AND substr(closing,1,10)<?",today);run("UPDATE jobs SET status='Closed' WHERE status='Open' AND source_id IS NOT NULL AND last_seen<datetime('now','-45 day')")}
async function syncAll(){const out=[];for(const s of q('SELECT * FROM sources WHERE enabled=1')){try{out.push(await syncSource(s))}catch(e){out.push({source:s.name,error:e.message})}}closeExpired();setSetting('last_sync',new Date().toISOString());return out}
function searchDb({query='',location='',type='',status='Open',verified,sourceId,limit:n=100}){let terms=String(query).split(/\s*,\s*| OR /i).map(x=>x.trim()).filter(Boolean);let sql=`SELECT ${SEL_J} FROM jobs WHERE 1=1`,a=[];if(status){sql+=' AND status=?';a.push(status)}if(terms.length){const parts=terms.map(t=>{const w=t.split(/\s+/);return'('+w.map(x=>{a.push(`%${x}%`,`%${x}%`,`%${x}%`);return'(title LIKE ? OR employer LIKE ? OR description LIKE ?)'}).join(' AND ')+')'});sql+=` AND (${parts.join(' OR ')})`}if(location&&!/newfoundland/i.test(location)){sql+=' AND location LIKE ?';a.push(`%${location}%`)}if(type){sql+=' AND type LIKE ?';a.push(`%${type}%`)}if(verified==='0'){sql+=' AND verified=0'}if(sourceId){sql+=' AND source_id=?';a.push(+sourceId)}sql+=' ORDER BY first_seen DESC,id DESC LIMIT ?';a.push(+n);return q(sql,...a).map(({requirements,...j})=>({...j,requirementCount:J(requirements,[]).length}))}
const parseHours=+(process.env.JOB_SYNC_HOURS||6);
// ---- Public + auth
app.get('/api/status',(req,res)=>res.json({ok:true,needsSetup:!q("SELECT id FROM users WHERE roles LIKE '%super_admin%' LIMIT 1").length,email:!!smtp}));
app.post('/api/setup',limit(5,6e4),h(async(req,res)=>{if(q("SELECT id FROM users WHERE roles LIKE '%super_admin%' LIMIT 1").length)throw E(403,'Setup is already complete');required(req.body,'name','email','password');if(!pwOk(req.body.password))throw E(400,'Password must be at least 10 characters');const r=run('INSERT INTO users(email,name,roles,hash) VALUES(?,?,?,?)',req.body.email,req.body.name,'["super_admin"]',hashPw(req.body.password));res.json({token:newSession(Number(r.lastInsertRowid))})}));
app.post('/api/login',limit(10,6e4),h(async(req,res)=>{const u=one('SELECT * FROM users WHERE email=? AND active=1',req.body.email||'');if(!u||!checkPw(req.body.password||'',u.hash))throw E(401,'Email or password is incorrect');res.json({token:newSession(u.id)})}));
app.post('/api/logout',(req,res)=>{const t=(req.headers.authorization||'').replace(/^Bearer /,'');run('DELETE FROM sessions WHERE token=?',crypto.createHash('sha256').update(t).digest('hex'));res.json({ok:true})});
app.get('/api/me',h(async(req,res)=>{if(!req.user)throw E(401,'Please sign in');res.json({id:req.user.id,name:req.user.name,email:req.user.email,roles:req.user.roles,staff:isStaff(req.user),participant:one('SELECT id,code FROM participants WHERE user_id=?',req.user.id)||null})}));
app.post('/api/password',h(async(req,res)=>{if(!req.user)throw E(401,'Please sign in');const u=one('SELECT hash FROM users WHERE id=?',req.user.id);if(!checkPw(req.body.current||'',u.hash))throw E(400,'Current password is incorrect');if(!pwOk(req.body.password))throw E(400,'Password must be at least 10 characters');run('UPDATE users SET hash=? WHERE id=?',hashPw(req.body.password),req.user.id);res.json({ok:true})}));
app.post('/api/invite/accept',limit(10,6e4),h(async(req,res)=>{const u=one('SELECT * FROM users WHERE invite=?',req.body.token||'x');if(!u)throw E(400,'This invitation link is invalid or has already been used');if(!pwOk(req.body.password))throw E(400,'Password must be at least 10 characters');run('UPDATE users SET hash=?,invite=NULL WHERE id=?',hashPw(req.body.password),u.id);res.json({token:newSession(u.id)})}));
app.post('/api/apply',limit(5,6e4),upload.single('cv'),h(async(req,res)=>{const d=req.body;required(d,'name','email','password');if(!/^\S+@\S+\.\S+$/.test(d.email))throw E(400,'Enter a valid email address');if(!pwOk(d.password))throw E(400,'Password must be at least 10 characters');if(one('SELECT id FROM users WHERE email=?',d.email))throw E(409,'An account already exists for this email. Please sign in instead.');
  let parsed=null;if(req.file)parsed=await parseCv(req.file.buffer,req.file.originalname);
  const u=run('INSERT INTO users(email,name,roles,hash) VALUES(?,?,?,?)',d.email,d.name,'["participant"]',hashPw(d.password));const pid=createParticipant({...d,source:d.source||'Public application'},'public',Number(u.lastInsertRowid));if(req.file)await addCv(pid,req.file,Number(u.lastInsertRowid));
  const p=getP(pid);await notify('application_received',p);res.json({token:newSession(Number(u.lastInsertRowid)),code:p.code})}));
// ---- Files
app.get('/api/files/:id',h(async(req,res)=>{if(!req.user)throw E(401,'Please sign in');const d=one('SELECT * FROM documents WHERE id=?',+req.params.id);if(!d)throw E(404,'File not found');if(!isStaff(req.user)){const p=participantOf(req);if(d.participant_id!==p.id&&!(d.participant_id==null&&d.programme_id))throw E(403,'Not permitted')}audit(req,'document.download','document',d.id);res.set('Content-Disposition',`attachment; filename="${d.name.replace(/[^\w.\- ]/g,'_')}"`);res.type(d.mime||'application/octet-stream').sendFile(path.join(DATA_DIR,'files',d.stored))}));
// ---- Staff: overview
const count=(sql,...a)=>one(`SELECT COUNT(*) c FROM ${sql}`,...a).c;
const FUNNEL=['Application received','Under review','Information session','Consent pending','Consent signed','Enrolled','Training','Activation pending','Employment Ready','Employed'];
app.get('/api/overview',staff,h(async(req,res)=>{const reached=FUNNEL.map(s=>({stage:s,count:count('stage_history WHERE stage=? AND participant_id IN (SELECT id FROM participants)',s)}));const seen=FUNNEL.map(s=>({stage:s,count:one('SELECT COUNT(DISTINCT participant_id) c FROM stage_history WHERE stage=?',s).c}));
  const places=q("SELECT CASE WHEN location='' OR location IS NULL THEN 'Location not stated' ELSE location END place,COUNT(*) n FROM jobs WHERE status='Open' GROUP BY place ORDER BY n DESC LIMIT 8");
  const outcomes=q("SELECT status,COUNT(*) n FROM referrals GROUP BY status");
  res.json({kpi:{participants:count("participants WHERE stage NOT IN('Not proceeding','Withdrawn')"),ready:count("participants WHERE stage='Employment Ready'"),vacancies:count("jobs WHERE status='Open'"),matchesToReview:count("matches m JOIN jobs j ON j.id=m.job_id WHERE m.reviewed=0 AND j.status='Open' AND m.eligibility<>'Not currently eligible' AND m.score>=50"),employed:count("outcomes WHERE status='Employed'")},funnel:seen,places,outcomes,tasks:{applications:count("participants WHERE stage IN('Application received','Under review')"),duplicates:count("participants WHERE duplicate_state='Needs review'"),sessions:count("participants WHERE stage='Under review'"),sessionsToday:count("info_sessions WHERE status='Scheduled' AND date(at)<=date('now')"),consents:count("consents WHERE status='Issued'"),enrol:count("participants WHERE stage='Consent signed'"),training:count("assignments WHERE status='Completed'"),activation:count("activations WHERE status IN('Scheduled','Completed')"),referrals:count("referrals WHERE status='Under Amal review'"),retention:count("outcomes WHERE status='Employed' AND ((d30 IS NULL AND date(start_date,'+30 day')<=date('now')) OR (d90 IS NULL AND date(start_date,'+90 day')<=date('now')) OR (d180 IS NULL AND date(start_date,'+180 day')<=date('now')))")},lastSync:setting('last_sync',null),activity:q('SELECT user_name,action,entity,at FROM audit ORDER BY id DESC LIMIT 8')})}));
// ---- Participants
app.get('/api/participants',staff,h(async(req,res)=>{let sql=`SELECT p.*,u.name staff_name,(SELECT MAX(version) FROM cv_versions c WHERE c.participant_id=p.id) cv FROM participants p LEFT JOIN users u ON u.id=p.staff_id WHERE 1=1`,a=[];const f=req.query;if(f.view==='applicants'){sql+=" AND p.stage IN('Application received','Under review','Information session','Consent pending','Consent signed')"}if(f.view==='participants'){sql+=" AND p.stage NOT IN('Application received','Under review','Information session','Consent pending','Consent signed')"}if(f.view==='ready')sql+=" AND p.stage='Employment Ready'";if(f.q){sql+=' AND (p.name LIKE ? OR p.email LIKE ? OR p.code LIKE ?)';a.push(`%${f.q}%`,`%${f.q}%`,`%${f.q}%`)}if(f.stage){sql+=' AND p.stage=?';a.push(f.stage)}if(f.staff){sql+=' AND p.staff_id=?';a.push(+f.staff)}sql+=' ORDER BY p.id DESC LIMIT 500';const rows=q(sql,...a).map(p=>{const out={...p,preferences:J(p.preferences,{})};if(f.view==='ready'){const c=latestCv(p.id);out.cvProfile=c?{skills:c.profile.skills,education:c.profile.education?.[0]?.label||'',months:c.profile.experienceMonths,languages:c.profile.languages,at:c.at}:null;out.activeReferrals=count("referrals WHERE participant_id=? AND status IN('Under Amal review','Approved for referral','Application submitted','Interview')",p.id)}return out});res.json(rows)}));
app.post('/api/participants',can('people.write'),h(async(req,res)=>{const d=req.body;required(d,'name');const id=createParticipant({...d,staff_id:d.staff_id||null},'staff',null,req);const p=getP(id);let inviteLink=null;if(d.email){if(!one('SELECT id FROM users WHERE email=?',d.email)){const invite=crypto.randomBytes(24).toString('hex');const u=run('INSERT INTO users(email,name,roles,invite) VALUES(?,?,?,?)',d.email,d.name,'["participant"]',invite);run('UPDATE participants SET user_id=? WHERE id=?',Number(u.lastInsertRowid),id);inviteLink=`${appUrl(req)}/#/invite/${invite}`;await notify('invite',p,{link:inviteLink},req)}await notify('application_received',p,{},req)}res.json({id,code:p.code,inviteLink,duplicate:p.duplicate_of})}));
app.get('/api/participants/:id',staff,h(async(req,res)=>{const p=getP(req.params.id),id=p.id;const cvs=q('SELECT id,version,document_id,file_type,method,word_count,profile,warnings,at FROM cv_versions WHERE participant_id=? ORDER BY version DESC',id).map(c=>({...c,profile:J(c.profile,{}),warnings:J(c.warnings,[])}));audit(req,'participant.view','participant',id);
  res.json({participant:{...p,preferences:J(p.preferences,{})},staff:one('SELECT name FROM users WHERE id=?',p.staff_id||0)?.name||null,duplicate:p.duplicate_of?one('SELECT id,code,name,email,phone,stage FROM participants WHERE id=?',p.duplicate_of):null,history:q('SELECT h.*,u.name by_name FROM stage_history h LEFT JOIN users u ON u.id=h.by_user WHERE participant_id=? ORDER BY h.id',id),cvs,sessions:q('SELECT * FROM info_sessions WHERE participant_id=? ORDER BY id DESC',id),consents:q('SELECT c.*,t.title,t.version FROM consents c JOIN consent_templates t ON t.id=c.template_id WHERE participant_id=? ORDER BY c.id DESC',id),assignments:q('SELECT a.*,pr.title,pr.required FROM assignments a JOIN programmes pr ON pr.id=a.programme_id WHERE participant_id=? ORDER BY pr.sort',id),activations:q('SELECT * FROM activations WHERE participant_id=? ORDER BY id DESC',id),matches:q(`SELECT m.id,m.score,m.eligibility,m.cv_id,c.version cv_version,j.id job_id,j.title,j.employer,m.at FROM matches m JOIN jobs j ON j.id=m.job_id JOIN cv_versions c ON c.id=m.cv_id WHERE m.participant_id=? ORDER BY m.score DESC LIMIT 25`,id),referrals:q('SELECT * FROM referrals WHERE participant_id=? ORDER BY id DESC',id),outcomes:q('SELECT * FROM outcomes WHERE participant_id=? ORDER BY id DESC',id),documents:q('SELECT id,kind,name,size,sha256,at FROM documents WHERE participant_id=? ORDER BY id DESC',id),messages:q('SELECT * FROM messages WHERE participant_id=? ORDER BY id DESC LIMIT 50',id),notes:q('SELECT n.*,u.name by_name FROM staff_notes n LEFT JOIN users u ON u.id=n.by_user WHERE participant_id=? ORDER BY n.id DESC',id)})}));
