app.post('/api/sessions',can('people.write'),h(async(req,res)=>{const d=req.body;required(d,'participant_id','at');const p=getP(d.participant_id);if(!['Application received','Under review','Information session'].includes(p.stage))throw E(409,`A session cannot be booked at stage "${p.stage}"`);const r=run('INSERT INTO info_sessions(participant_id,at,location,staff_id) VALUES(?,?,?,?)',p.id,d.at,d.location||'',d.staff_id||req.user.id);if(p.stage!=='Information session')setStage(req,p.id,'Information session','Session scheduled');await notify('session_scheduled',p,{when:new Date(d.at).toLocaleString('en-CA'),location:d.location||'details to follow'},req);res.json({id:Number(r.lastInsertRowid)})}));
