app.post('/api/assignments',can('training.write'),h(async(req,res)=>{const d=req.body;const ids=[].concat(d.participant_ids||[]).map(Number),prs=d.pathway?q('SELECT id FROM programmes WHERE required=1 AND active=1').map(x=>x.id):[].concat(d.programme_ids||[]).map(Number);if(!ids.length||!prs.length)throw E(400,'Choose participants and programmes');let n=0;for(const pid of ids){const p=getP(pid);if(!['Enrolled','Training','Activation pending','Employment Ready'].includes(p.stage))throw E(409,`${p.name} must be enrolled before training can be assigned`);for(const pr of prs){const r=run('INSERT OR IGNORE INTO assignments(participant_id,programme_id,deadline) VALUES(?,?,?)',pid,pr,d.deadline||null);n+=Number(r.changes);if(r.changes)await notify('training_assigned',p,{programme:one('SELECT title FROM programmes WHERE id=?',pr).title,deadline:d.deadline||'none set'},req)}if(p.stage==='Enrolled')setStage(req,pid,'Training','Training assigned')}audit(req,'training.assign','assignment','',{ids,prs});res.json({created:n})}));
app.patch('/api/assignments/:id',can('training.write'),h(async(req,res)=>{const a=one('SELECT * FROM assignments WHERE id=?',+req.params.id);if(!a)throw E(404,'Not found');const d=req.body;for(const k of['attendance','assessment','evidence','deadline'])if(k in d)run(`UPDATE assignments SET ${k}=? WHERE id=?`,d[k],a.id);if(d.status){if(!['Not started','In progress','Completed'].includes(d.status))throw E(400,'Use the verify action to verify completion');run("UPDATE assignments SET status=?,completed_at=CASE WHEN ?='Completed' THEN CURRENT_TIMESTAMP ELSE completed_at END,verified_by=NULL,verified_at=NULL WHERE id=?",d.status,d.status,a.id)}audit(req,'assignment.update','assignment',a.id,d);res.json({ok:true})}));
app.post('/api/assignments/:id/verify',can('training.write'),h(async(req,res)=>{const a=one('SELECT * FROM assignments WHERE id=?',+req.params.id);if(!a)throw E(404,'Not found');if(a.status!=='Completed')throw E(409,'The assignment must be marked completed before it can be verified');if(!a.attendance||!a.assessment)throw E(409,'Record attendance and assessment outcome before verifying');run("UPDATE assignments SET status='Verified',verified_by=?,verified_at=CURRENT_TIMESTAMP WHERE id=?",req.user.id,a.id);audit(req,'assignment.verify','assignment',a.id);if(progressGate(req,a.participant_id)&&getP(a.participant_id).stage==='Training')setStage(req,a.participant_id,'Activation pending','All required training verified');res.json({ok:true})}));
