app.patch('/api/activations/:id',can('training.write'),h(async(req,res)=>{const a=one('SELECT * FROM activations WHERE id=?',+req.params.id);if(!a)throw E(404,'Not found');const d=req.body;if(d.action==='record'){required(d,'attendance','assessment');run("UPDATE activations SET attendance=?,assessment=?,notes=?,status='Completed' WHERE id=?",d.attendance,d.assessment,d.notes||'',a.id)}else if(d.action==='approve'){if(a.status!=='Completed')throw E(409,'Record the session outcome first');if(!/attended/i.test(a.attendance||'')||!/pass/i.test(a.assessment||''))throw E(409,'Only an attended and passed session can be approved');if(!progressGate(req,a.participant_id))throw E(409,'Required training is no longer fully verified');if(!one("SELECT id FROM consents WHERE participant_id=? AND status='Signed'",a.participant_id))throw E(409,'A valid signed consent is required');run("UPDATE activations SET status='Approved',approved_by=?,approved_at=CURRENT_TIMESTAMP WHERE id=?",req.user.id,a.id);setStage(req,a.participant_id,'Employment Ready','Activation approved');await notify('employment_ready',getP(a.participant_id),{},req)}else if(d.action==='cancel')run("UPDATE activations SET status='Cancelled' WHERE id=?",a.id);audit(req,'activation.'+d.action,'activation',a.id);res.json({ok:true})}));
