app.get('/api/match/job/:id',staff,h(async(req,res)=>{const latest=`m.cv_id=(SELECT id FROM cv_versions WHERE participant_id=m.participant_id ORDER BY version DESC LIMIT 1)`;res.json(q(`SELECT m.*,p.name,p.code,p.availability,c.version cv_version,c.document_id FROM matches m JOIN participants p ON p.id=m.participant_id JOIN cv_versions c ON c.id=m.cv_id WHERE m.job_id=? AND ${latest} ORDER BY (m.eligibility='Not currently eligible'),m.score DESC`,+req.params.id).map(matchRow).map(m=>{m.previousReferrals=count('referrals WHERE participant_id=? AND (job_id=? OR employer=?)',m.participant_id,m.job_id,one('SELECT employer FROM jobs WHERE id=?',m.job_id).employer||'-');m.hasReferral=!!one('SELECT id FROM referrals WHERE participant_id=? AND job_id=?',m.participant_id,m.job_id);return m}))}));
