app.get('/api/referrals',staff,(req,res)=>res.json(q(`SELECT r.*,p.name,p.code,c.version cv_version,c.document_id,m.score,m.eligibility,m.result,j.url,(SELECT COUNT(*) FROM referrals x WHERE x.participant_id=r.participant_id AND x.employer=r.employer AND x.id<>r.id) previous FROM referrals r JOIN participants p ON p.id=r.participant_id LEFT JOIN cv_versions c ON c.id=r.cv_id LEFT JOIN matches m ON m.id=r.match_id LEFT JOIN jobs j ON j.id=r.job_id ORDER BY r.id DESC LIMIT 500`).map(r=>({...r,result:J(r.result,null)}))));
app.post('/api/referrals',can('jobs.write'),h(async(req,res)=>{required(req.body,'match_id');const m=one('SELECT * FROM matches WHERE id=?',+req.body.match_id);if(!m)throw E(404,'Match not found');const p=getP(m.participant_id);if(p.stage!=='Employment Ready')throw E(409,'Only Employment Ready participants can be referred');if(one('SELECT id FROM referrals WHERE participant_id=? AND job_id=?',m.participant_id,m.job_id))throw E(409,'A referral already exists for this participant and vacancy');const j=one('SELECT * FROM jobs WHERE id=?',m.job_id);const r=run('INSERT INTO referrals(match_id,job_id,participant_id,cv_id,created_by,job_title,employer) VALUES(?,?,?,?,?,?,?)',m.id,j.id,p.id,m.cv_id,req.user.id,j.title,j.employer);run('UPDATE matches SET reviewed=1 WHERE id=?',m.id);audit(req,'referral.create','referral',Number(r.lastInsertRowid));res.json({id:Number(r.lastInsertRowid)})}));
app.post('/api/referrals/:id/decide',can('jobs.write'),h(async(req,res)=>{const d=req.body,r=one('SELECT * FROM referrals WHERE id=?',+req.params.id);if(!r)throw E(404,'Not found');const map={approve:'Approved for referral',info:'More information requested',hold:'On hold',decline:'Declined'};if(!map[d.action])throw E(400,'Unknown decision');if(d.action==='decline'&&!String(d.note||'').trim())throw E(400,'A reason is required to decline');if(d.action==='approve'){const m=one('SELECT eligibility,result FROM matches WHERE id=?',r.match_id);if(m?.eligibility==='Not currently eligible')throw E(409,'A confirmed mandatory mismatch blocks this referral. Correct or review the requirement first.');if(m?.eligibility==='Verification required'&&!d.acknowledge)throw E(409,'Mandatory requirements still need verification. Verify them or confirm that you reviewed them.')}run('UPDATE referrals SET status=?,decision_note=?,decided_by=?,decided_at=CURRENT_TIMESTAMP WHERE id=?',map[d.action],d.note||'',req.user.id,r.id);audit(req,'referral.'+d.action,'referral',r.id,{note:d.note,acknowledged:!!d.acknowledge});if(d.action==='approve'){const j=one('SELECT url FROM jobs WHERE id=?',r.job_id||0);await notify('referral_approved',getP(r.participant_id),{job:r.job_title,employer:r.employer,note:d.note||'Your advisor will contact you.',url:j?.url||''},req)}res.json({ok:true})}));
