const P_READY=p=>['Employment Ready','Employed'].includes(p.stage);
const portalJobs=p=>{if(!P_READY(p))return[];return q(`SELECT DISTINCT j.id,j.title,j.employer,j.location,j.type,j.closing,j.url,r.status referral_status,r.decision_note,m.result FROM referrals r JOIN jobs j ON j.id=r.job_id LEFT JOIN matches m ON m.id=r.match_id WHERE r.participant_id=? AND r.status NOT IN('Under Amal review','On hold','Declined','More information requested') ORDER BY r.id DESC`,p.id).map(j=>{const r=J(j.result,null);delete j.result;return{...j,suitability:r?{eligibility:r.eligibility,explanation:r.explanation}:null}})};
