app.post('/api/portal/cv',upload.single('cv'),h(async(req,res)=>{const p=participantOf(req);if(!req.file)throw E(400,'Choose a file');const c=await addCv(p.id,req.file,req.user.id);audit(req,'cv.upload','participant',p.id,{version:c.version,by:'participant'});res.json({version:c.version,method:c.method,warnings:c.warnings})}));
app.patch('/api/portal/profile',h(async(req,res)=>{const p=participantOf(req),d=req.body;for(const k of['phone','city'])if(k in d)run(`UPDATE participants SET ${k}=? WHERE id=?`,d[k],p.id);if(['Available for opportunities','Currently interviewing or awaiting outcomes','Temporarily unavailable'].includes(d.availability))run('UPDATE participants SET availability=? WHERE id=?',d.availability,p.id);if(d.preferences)run('UPDATE participants SET preferences=? WHERE id=?',JSON.stringify(d.preferences),p.id);if(d.cvProfile){const c=latestCv(p.id);if(!c)throw E(409,'Upload a CV first');const pr={...c.profile};for(const k of['skills','certifications','languages'])if(Array.isArray(d.cvProfile[k]))pr[k]=d.cvProfile[k];const extra=[...pr.skills,...pr.certifications,...pr.languages].filter(x=>!(pr.lines||[]).some(l=>l.text.includes(x)));pr.lines=[...(pr.lines||[]).filter(l=>l.section!=='participant-confirmed'),...extra.map(x=>({page:0,section:'participant-confirmed',text:x}))];const v=(one('SELECT MAX(version) v FROM cv_versions WHERE participant_id=?',p.id).v)+1;run('INSERT INTO cv_versions(participant_id,version,document_id,file_type,method,word_count,text,profile,warnings,by_user) VALUES(?,?,?,?,?,?,?,?,?,?)',p.id,v,c.document_id,c.file_type,'Participant-corrected profile',c.word_count,c.text,JSON.stringify(pr),'[]',req.user.id)}audit(req,'profile.update','participant',p.id,Object.keys(d));res.json({ok:true})}));
app.post('/api/portal/consents/:id/sign',h(async(req,res)=>{const p=participantOf(req);const c=one('SELECT c.*,t.sha256 tsha FROM consents c JOIN consent_templates t ON t.id=c.template_id WHERE c.id=? AND participant_id=?',+req.params.id,p.id);if(!c)throw E(404,'Consent not found');if(c.status!=='Issued')throw E(409,'This consent is not awaiting signature');if(norm(req.body.signed_name)!==norm(p.name))throw E(400,`Type your full name exactly as registered: ${p.name}`);if(!req.body.agree)throw E(400,'Confirm that you have read and agree');run("UPDATE consents SET status='Signed',signed_at=CURRENT_TIMESTAMP,signed_name=?,signed_ip=?,signed_ua=?,sha256=? WHERE id=?",req.body.signed_name,req.ip,(req.headers['user-agent']||'').slice(0,200),c.tsha,c.id);audit(req,'consent.sign','consent',c.id,{document_sha256:c.tsha});setStage(req,p.id,'Consent signed','Signed electronically');res.json({ok:true})}));
