const web=path.join(__dirname,'..','docs');app.use(express.static(web));
app.use('/api',(req,res)=>res.status(404).json({error:'Not found'}));
app.get('*',(req,res)=>res.sendFile(path.join(web,'index.html')));
app.use((e,req,res,next)=>{if(e instanceof multer.MulterError)return res.status(413).json({error:e.code==='LIMIT_FILE_SIZE'?'That file is larger than the 15 MB limit.':e.message});if(!e.expose&&!(e instanceof CvError))console.error(e);res.status(e.status||500).json({error:e.expose||e instanceof CvError?e.message:'Something went wrong on the server. Please try again.'})});
const port=process.env.PORT||8787;
if(require.main===module){app.listen(port,()=>console.log(`Amal Connect running at http://localhost:${port}`));if(parseHours>0){setTimeout(()=>syncAll().catch(console.error),2e4);setInterval(()=>syncAll().catch(console.error),parseHours*36e5)}}
module.exports=app;
